const FAQ_WORD_COUNT = EU_GCC_ENTRY_FAQ.reduce(
  (sum, item) => sum + countWords(item.question) + countWords(item.answer),
  0,
);

/** Article words: summary + narrative + FAQ. The bibliography is excluded from the band. */
export const EU_GCC_ENTRY_WORD_COUNT =
  countWords(EU_GCC_ENTRY_EXECUTIVE_SUMMARY_HTML) + countWords(NARRATIVE_HTML) + FAQ_WORD_COUNT;

const READING_WORDS_PER_MINUTE = 225;

export const EU_GCC_ENTRY_READING_TIME = Math.ceil(
  (countWords(EU_GCC_ENTRY_EXECUTIVE_SUMMARY_HTML) + countWords(NARRATIVE_HTML) + FAQ_WORD_COUNT) /
    READING_WORDS_PER_MINUTE,
);

